// Package thirdparty embeds the third-party notices of everything compiled into
// the aggrega binary.
package thirdparty

import _ "embed"

//go:embed THIRD-PARTY-NOTICES.txt
var notices string

// Notices returns the third-party notices text for the host and every guest the
// binary embeds: each dependency with its licence and copyright lines, then each
// licence text once. The text is generated by scripts/gen-third-party-licenses.sh.
func Notices() string { return notices }
